WITH p AS (SELECT %s::date d1,%s::date d2,coalesce(%s::text,'') ma_dvcs,%s::integer uid,%s::integer lim),s AS (SELECT p.*,u.user_id ok,coalesce(u.ds_branchs,'') bs,coalesce(u.is_super,0)=1 OR coalesce(u.ds_branchs,'')='' allb FROM p LEFT JOIN public.userinfo u ON u.user_id=p.uid) SELECT a.ma_dvcs,a.stt_rec,a.ngay_ct,a.so_ct,a.ma_sp,a.ma_vt,a.ma_lo,a.so_luong,a.so_luong_ok,a.so_luong_ng,a.ket_qua,a.status,count(*) OVER() total FROM public.phpqc a CROSS JOIN s WHERE s.ok IS NOT NULL AND a.ngay_ct BETWEEN s.d1 AND s.d2 AND(s.ma_dvcs='' OR a.ma_dvcs=ANY(string_to_array(s.ma_dvcs,',')))AND(s.allb OR a.ma_dvcs=ANY(string_to_array(s.bs,','))) ORDER BY a.ngay_ct DESC,a.so_ct LIMIT(SELECT lim FROM p);
